pair<int, int> acmTeam(const vector<string>& topic) {
    int most = 0;
    int most_cnt = 0;
    int n = topic.size();

    for (int i = 0; i < n - 1; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int x = 0;
            for (int k = 0; k < topic[i].size(); ++k) {
                if (topic[i][k] == '1' || topic[j][k] == '1') {
                    x++;
                }
            }
            if (x > most) {
                most = x;
                most_cnt = 1;
            } else if (x == most) {
                most_cnt++;
            }
        }
    }
    return {most, most_cnt};
}

int main() {
    int n, m;
    cin >> n >> m;
    cin.ignore(); // To ignore the newline after the integers

    vector<string> topic(n);
    for (int i = 0; i < n; ++i) {
        getline(cin, topic[i]);
    }

    auto result = acmTeam(topic);
    cout << result.first << endl << result.second << endl;

    return 0;
}

