    int res = 0;
    int maxA = *max_element(a.begin(), a.end());
    int minB = *min_element(b.begin(), b.end());

    for (int i = maxA; i <= minB; ++i) {
        bool isValid = true;

        for (int aa : a) {
            if (i % aa != 0) {
                isValid = false;
                break;
            }
        }

        if (isValid) {
            for (int bb : b) {
                if (bb % i != 0) {
                    isValid = false;
                    break;
                }
            }
        }

        if (isValid) {
            res++;
        }
    }

    return res;
}

