vector<int> circularArrayRotation(const vector<int>& a, int k, const vector<int>& queries) {
    int n = a.size();
    int x = k % n;
    vector<int> rotated(n);

    // Rotate the array
    for (int i = 0; i < n; ++i) {
        rotated[i] = a[(i - x + n) % n];
    }

    vector<int> res;
    for (int q : queries) {
        res.push_back(rotated[q]);
    }
    return res;
}

int main() {
    int n, k, q;
    cin >> n >> k >> q;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> queries(q);
    for (int i = 0; i < q; ++i) {
        cin >> queries[i];
    }

    vector<int> result = circularArrayRotation(a, k, queries);

    for (int res : result) {
        cout << res << endl;
    }

    return 0;
}

