vector<int> climbingLeaderboard(vector<int> ranked, vector<int> player) {
    vector<int> res;
    vector<pair<int, int>> x;
    x.emplace_back(ranked[0], 1);

    for (size_t i = 1; i < ranked.size(); ++i) {
        if (ranked[i] != x.back().first) {
            x.emplace_back(ranked[i], x.back().second + 1);
        }
    }

    int i = x.size() - 1;
    for (int p : player) {
        while (i >= 0 && p > x[i].first) {
            i--;
        }
        if (i < 0) {
            res.push_back(1);
        } else if (p == x[i].first) {
            res.push_back(x[i].second);
        } else {
            res.push_back(x[i].second + 1);
        }
    }

    return res;
}

int main() {
