    }

    int player_count;
    cin >> player_count;
    vector<int> player(player_count);

    for (int i = 0; i < player_count; ++i) {
        cin >> player[i];
    }

    vector<int> result = climbingLeaderboard(ranked, player);

    for (size_t i = 0; i < result.size(); ++i) {
