int queensAttack(int n, int k, int r_q, int c_q, vector<vector<int>>& obstacles) {
    // Keep track of closest obstacles.
    int row_left = 0;
    int row_right = n + 1;
    int col_up = n + 1;
    int col_down = 0;
    auto f = [&](int x) { return n - x + 1; };
    int d1_up = (r_q + c_q + 2 * (n - max(r_q, c_q))) / 2 + 1;
    int d1_down = (r_q + c_q - 2 * min(r_q, c_q)) / 2;
    int d1_q = (r_q + c_q) / 2;
    int d2_up = (f(r_q) + c_q - 2 * min(f(r_q), c_q)) / 2;
    int d2_down = (f(r_q) + c_q + 2 * (n - max(f(r_q), c_q))) / 2 + 1;
    int d2_q = (f(r_q) + c_q) / 2;
    int d_q = r_q - c_q;
    int s_q = r_q + c_q;

    for (const auto& obstacle : obstacles) {
        int r_o = obstacle[0];
        int c_o = obstacle[1];
        if (r_o == r_q) {
            if (c_o > c_q) {
                row_right = min(row_right, c_o);
            } else {
                row_left = max(row_left, c_o);
            }
        } else if (c_o == c_q) {
            if (r_o > r_q) {
                col_up = min(col_up, r_o);
            } else {
                col_down = max(col_down, r_o);
            }
        } else if (r_o - c_o == d_q) {
            int d1_o = (r_o + c_o) / 2;
            if (r_o > r_q) {
                d1_up = min(d1_up, d1_o);
            } else {
                d1_down = max(d1_down, d1_o);
            }
        } else if (r_o + c_o == s_q) {
            int d2_o = (f(r_o) + c_o) / 2;
            if (c_o > c_q) {
                d2_down = min(d2_down, d2_o);
            } else {
                d2_up = max(d2_up, d2_o);
            }
        }
    }
    return (row_right - row_left + col_up - col_down +
            d1_up - d1_down + d2_down - d2_up - 8);
}

