        int i1, j1, i2, j2;
        cin >> i1 >> j1 >> i2 >> j2;
        t_exit[{i1 - 1, j1 - 1}] = {i2 - 1, j2 - 1};
        t_exit[{i2 - 1, j2 - 1}] = {i1 - 1, j1 - 1};
    }

    vector<pair<int, int>> states = { {-1, -1} }; // Death state.
    map<pair<int, int>, int> state2idx;
    vector<double> v = { 0.0 }; // State values, i.e. probability.
    int s_init = -1;
    vector<vector<pair<int, double>>> transitions(1, { {0, 1.0} }); // Self loop when dead.

    for (int i1 = 0; i1 < n; ++i1) {
        for (int j1 = 0; j1 < m; ++j1) {
            char x = board[i1][j1];
            if (x == 'A' || x == '%' || x == 'O') {
                state2idx[{i1, j1}] = states.size();
                states.push_back({i1, j1});
            } else if (x == '#' || x == '*') {
                state2idx[{i1, j1}] = 0;       
            } else {
                assert(false);
            }
        }
    }

    for (int i1 = 0; i1 < n; ++i1) {
        for (int j1 = 0; j1 < m; ++j1) {
            char x = board[i1][j1];
            int state_idx = state2idx[{i1, j1}];
            if (x == 'A' || x == '%' || x == 'O') {
                if (x == 'A') {
                    s_init = state_idx;
                    v.push_back(0.0);
                } else if (x == '%') {
                    v.push_back(1.0);
                    transitions.push_back({ {state_idx, 1.0} }); // Self loop when exit.
                } else if (x == 'O') {
                    v.push_back(0.0);
                } else {
                    assert(false);
                }
                if (x == 'A' || x == 'O') {
                    auto [i2, j2] = t_exit.count({i1, j1}) ? t_exit[{i1, j1}] : make_pair(i1, j1);
                    vector<pair<int, double>> succs;
                    int deaths = 0;
                    for (auto [a, b] : vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
                        int i3 = i2 + a, j3 = j2 + b;
                        if (0 <= i3 && i3 < n && 0 <= j3 && j3 < m) {
                            char y = board[i3][j3];
                            if (y == 'A' || y == '%' || y == 'O') {
                                succs.push_back({state2idx[{i3, j3}], 1.0});
                            } else if (y == '*') {
                                deaths++;
                            }
                        }
                    }
                    if (succs.empty()) {
                        transitions.push_back({ {0, 1.0} });
                    } else {
                        double total = succs.size() + deaths;
                        for (auto& s : succs) {
                            s.second = 1.0 / total;
                        }
                        if (deaths > 0) {
                            succs.push_back({0, static_cast<double>(deaths) / total});
                        }
                        transitions.push_back(succs);
                    }
                }
            }
        }
    }

    while (true) {
        vector<double> v_old = v;
        for (int state = 0; state < states.size(); ++state) {
            double x = 0.0;
            for (auto [succ, prob] : transitions[state]) {
                x += v[succ] * prob;
            }
            v[state] = x;
        }
        bool keep_going = false;
        for (int state = 0; state < states.size(); ++state) {
            if (abs(v[state] - v_old[state]) > 1e-10) {
                keep_going = true;
                break;
            }
        }
        if (!keep_going) {
            break;
        }
    }

    cout << v[s_init] << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>

using namespace std;

int cost(const vector<int>& B) {
    int a = 0;
    int b = 0;
    int bi = B[0];
    for (size_t i = 1; i < B.size(); ++i) {
        int aa = max(a, b + bi - 1);
        int bb = max(b + abs(bi - B[i]), a + B[i] - 1);
        a = aa;
        b = bb;
        bi = B[i];
    }
    return max(a, b);
}

int main() {
    int t;
    cin >> t;
    cin.ignore(); // To ignore the newline after the integer input

    for (int t_itr = 0; t_itr < t; ++t_itr) {
        int n;
        cin >> n;
        vector<int> B(n);
        for (int i = 0; i < n; ++i) {
            cin >> B[i];
        }

        int result = cost(B);
        cout << result << endl;
    }

    return 0;
}
